<?php $title='Services';require __DIR__.'/../layouts/header.php';?><div class="pagehead"><div><h1>Service Catalog</h1><p>Each service can define requirements, workflows, approvals and automation.</p></div><?php if(Auth::can('Service','configure')):?><a class="primary" href="<?=route('service.create')?>">+ Add Service</a><?php endif;?></div><div class="service-grid"><?php foreach($services as $s):?><a class="service-card" href="<?=route('service.view',['id'=>$s['id']])?>"><span><?=e($s['category'])?></span><strong><?=e($s['name'])?></strong><span><?=money((float)$s['price'])?> · <?=$s['request_count']?> active requests</span></a><?php endforeach;?></div><?php require __DIR__.'/../layouts/footer.php';?>
